import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.D7EuCHIT.js";const m=JSON.parse('{"title":"类型、范围与跨字段校验","description":"","frontmatter":{},"headers":[],"relativePath":"config/validation.md","filePath":"config/validation.md","lastUpdated":1791730262000}'),r={name:"config/validation.md"};function o(n,a,s,d,c,h){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="类型、范围与跨字段校验" tabindex="-1">类型、范围与跨字段校验 <a class="header-anchor" href="#类型、范围与跨字段校验" aria-label="Permalink to &quot;类型、范围与跨字段校验&quot;">​</a></h1><p>先检查 TOML 语法，再检查与 defaults/schema 的类型一致，最后由宿主检查范围与跨字段约束。默认键是字符串/数值/布尔三类，不强制把所有整数形式字段当作独立整数类型。</p><h2 id="已确认的约定" tabindex="-1">已确认的约定 <a class="header-anchor" href="#已确认的约定" aria-label="Permalink to &quot;已确认的约定&quot;">​</a></h2><ul><li>UI 数值要求有限，NaN/Infinity 不能作为有效数值进入配置。</li><li>颜色是字符串，长度 7 或 9，格式 #RRGGBB / #AARRGGBB。</li><li>播放模式 ID 必须为 0..2147483647 的整数；是否有提供者支持该模式由模式目录决定。</li><li>个人分类歌词预算 &gt;0 且 ≤4194304 字节；语言阈值还有本地规则界限。</li><li>仓库 timeout 为 1000..60000 ms、maximum_rows ≤32、index_limit_bytes ≤1048576；其他字段也有共同界限。</li><li>插件动态参数按声明 MINIMUM/MAXIMUM/INTEGER 检查。</li></ul><p>字号、透明度、布局、过渡和粒子/波纹相关字段还包含各自约束；完整参数组合应通过宿主配置接口写入并验证。不要猜测跨字段组合能自动通过。</p><h2 id="为什么不直接接受未知字段" tabindex="-1">为什么不直接接受未知字段 <a class="header-anchor" href="#为什么不直接接受未知字段" aria-label="Permalink to &quot;为什么不直接接受未知字段&quot;">​</a></h2><p>未知键可由声明 schema 的插件接管，也可以通过声明表读取。没有注册 schema 或消费路径就不自动成为新功能。未知字段列表用于诊断；不能把“文件未报错”理解为功能已生效。</p><h2 id="原子激活" tabindex="-1">原子激活 <a class="header-anchor" href="#原子激活" aria-label="Permalink to &quot;原子激活&quot;">​</a></h2><p>写入会保留其他配置与注释，参数校验通过后请求帧边界激活。插件不要在 worker 绕过配置模块直接改当前模型，也不要在每帧把同一值反复写到磁盘。</p><p>下一步：<a href="/LyraPlayer-docs-site/config/reference/">所有默认键</a>。</p>',10)])])}const p=e(r,[["render",o]]);export{m as __pageData,p as default};
